selector_to_html = {"a[href=\"../dispatch_user_guide/dispatch-user-guide.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Operator dispatch user guide<a class=\"headerlink\" href=\"#operator-dispatch-user-guide\" title=\"Link to this heading\">#</a></h1><p>This guide describes how to use an operator dispatch system that selects between FlagGems, vendor-specific, and PyTorch reference implementations. The selection follows a priority hierarchy, from highest to lowest:</p>", "a[href=\"../dispatch_user_guide/configure-backend-selection.html#environment-variables\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Environment variables<a class=\"headerlink\" href=\"#environment-variables\" title=\"Link to this heading\">#</a></h2><p>Environment variables can override specific items from platform config. If not set, values from platform config file are used.</p>", "a[href=\"run-inference-task.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Run an inference task<a class=\"headerlink\" href=\"#run-an-inference-task\" title=\"Link to this heading\">#</a></h1><p>With vLLM and vllm-plugin-FL <a class=\"reference internal\" href=\"install.html\"><span class=\"std std-doc\">installed</span></a>, you can run inference in two ways: offline batched inference (load the model directly in a Python script) or serving inference (start an API server and send requests). Choose the approach that fits your use case.</p>", "a[href=\"requirements.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Requirements<a class=\"headerlink\" href=\"#requirements\" title=\"Link to this heading\">#</a></h1><h2>Software Requirements<a class=\"headerlink\" href=\"#software-requirements\" title=\"Link to this heading\">#</a></h2><p>The following table summarizes the required software and the version supported by each release of vllm-plugin-FL:</p>", "a[href=\"#use-native-cuda-operators\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Use native CUDA operators<a class=\"headerlink\" href=\"#use-native-cuda-operators\" title=\"Link to this heading\">#</a></h4><p>If you want to use the original CUDA operators, you can set the following environment variables.</p>", "a[href=\"../overview/overview.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">vllm-plugin-FL Overview<a class=\"headerlink\" href=\"#vllm-plugin-fl-overview\" title=\"Link to this heading\">#</a></h1><p>vllm-plugin-FL is a plugin for the <a class=\"reference external\" href=\"https://github.com/vllm-project/vllm\">vLLM</a> inference/serving framework, built on top of <a class=\"reference external\" href=\"https://flagos.io\">FlagOS</a>, a unified open-source AI system software stack. vllm-plugin-FL extends vLLM\u2019s capabilities and performance across diverse hardware environments. Without changing vLLM\u2019s original interfaces or usage patterns, the same command can run model inference/serving on different chips. vllm-plugin-FL works with other FlagOS components, including the unified operator library <a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagGems\">FlagGems</a>, the unified communication library <a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagCX\">FlagCX</a>, and the unified compiler <a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree\">FlagTree</a>.</p><p>vllm-plugin-FL is installed from a Docker image and then integrates vLLM with the FlagOS operator, communication, and compiler stack on the target chip. See <a class=\"reference internal\" href=\"../getting_started/getting-started.html\"><span class=\"std std-doc\">Getting Started</span></a> for the installation flow and <a class=\"reference internal\" href=\"../overview/features.html\"><span class=\"std std-doc\">Features</span></a> for what the plugin provides.</p>", "a[href=\"#install-software-for-running-an-inference-task\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Install software for running an inference task<a class=\"headerlink\" href=\"#install-software-for-running-an-inference-task\" title=\"Link to this heading\">#</a></h1><h2>Install from docker image<a class=\"headerlink\" href=\"#install-from-docker-image\" title=\"Link to this heading\">#</a></h2><p>vllm-plugin-FL is installed from a pre-built Docker image. The supported versions and hardware platforms are listed in <a class=\"reference internal\" href=\"requirements.html\"><span class=\"std std-doc\">Requirements</span></a>.</p>", "a[href=\"#additional-setup-for-huawei-ascend\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Additional setup for Huawei Ascend<a class=\"headerlink\" href=\"#additional-setup-for-huawei-ascend\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#dispatch-operators\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Dispatch operators<a class=\"headerlink\" href=\"#dispatch-operators\" title=\"Link to this heading\">#</a></h3><p>If needed, you can also dispatch operators.</p><p>For concept related information, see <a class=\"reference internal\" href=\"../overview/overview.html\"><span class=\"std std-doc\">vllm-plugin-FL Overview</span></a>.\nFor configuration related information, see <a class=\"reference internal\" href=\"../dispatch_user_guide/dispatch-user-guide.html\"><span class=\"std std-doc\">Operator dispatch user guide</span></a>.</p>", "a[href=\"#additional-setup-for-cuda\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Additional setup for CUDA<a class=\"headerlink\" href=\"#additional-setup-for-cuda\" title=\"Link to this heading\">#</a></h3><p>This section illustrates how to run an inference task with CUDA through setting environment variables.</p><p>For operator dispatch environment variables, see <a class=\"reference internal\" href=\"../dispatch_user_guide/configure-backend-selection.html#environment-variables\"><span class=\"std std-ref\">Environment variables</span></a>.</p>", "a[href=\"#install-from-docker-image\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Install from docker image<a class=\"headerlink\" href=\"#install-from-docker-image\" title=\"Link to this heading\">#</a></h2><p>vllm-plugin-FL is installed from a pre-built Docker image. The supported versions and hardware platforms are listed in <a class=\"reference internal\" href=\"requirements.html\"><span class=\"std std-doc\">Requirements</span></a>.</p>", "a[href=\"#version-compatibility\"]": "<p id=\"version-compatibility\">Pick the branch that matches your vLLM version; the branch and the vLLM version must stay paired:</p>", "a[href=\"#use-cuda-communication-library\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Use CUDA communication library<a class=\"headerlink\" href=\"#use-cuda-communication-library\" title=\"Link to this heading\">#</a></h4>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
